source='''from collections import Counter, deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    frames = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if not color or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            while q:
                y, x = q.popleft()
                comp.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and (ny,nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny,nx))
                        q.append((ny,nx))
            r0, r1 = min(y for y,x in comp), max(y for y,x in comp)
            c0, c1 = min(x for y,x in comp), max(x for y,x in comp)
            if r1-r0 < 2 or c1-c0 < 2:
                continue
            border = {(y,x) for y in range(r0,r1+1) for x in range(c0,c1+1)
                      if y in (r0,r1) or x in (c0,c1)}
            if set(comp) == border:
                frames.append((color, r0, r1, c0, c1, border))
    frame_cells = set().union(*(f[5] for f in frames)) if frames else set()
    markers = Counter(grid[r][c] for r in range(h) for c in range(w)
                      if grid[r][c] and (r,c) not in frame_cells)
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] and (r,c) not in frame_cells:
                out[r][c] = 0
    used = set()
    for _, r0, r1, c0, c1, _ in sorted(frames, key=lambda f: (f[1], f[3])):
        inner_h, inner_w = r1-r0-1, c1-c0-1
        counts = Counter(((y-r0-1)+(x-c0-1)) % 2
                         for y in range(r0+1,r1) for x in range(c0+1,c1))
        candidates = [color for color,n in markers.items() if color not in used and n in counts.values()]
        if not candidates:
            continue
        color = candidates[0]
        used.add(color)
        parity = next(p for p,n in counts.items() if n == markers[color])
        for y in range(r0+1,r1):
            for x in range(c0+1,c1):
                if ((y-r0-1)+(x-c0-1)) % 2 == parity:
                    out[y][x] = color
    return out
